347	function record(value: unknown, label: string): Record<string, unknown> {
348		if (!value || typeof value !== 'object' || Array.isArray(value))
349			throw new Error(`Corpus conformance ${label} must be an object`);
350		return value as Record<string, unknown>;
351	}
352	
353	function string(value: unknown, label: string): string {
354		if (typeof value !== 'string' || value.length === 0)
355			throw new Error(`Corpus conformance ${label} must be a non-empty string`);
356		return value;
357	}
