359	async function readJson(file: string): Promise<unknown> {
360		return JSON.parse(await readFile(file, 'utf8'));
361	}
362	
363	function sourceIdentity(receipt: MigrationReceipt): Record<string, string> {
364		const parsed = parseURL(receipt.source.repository);
365		if (parsed.protocol !== 'https:' || !parsed.host || !parsed.pathname)
366			throw new Error(
367				`Corpus source repository is not a canonical HTTPS URL: ${receipt.fixture}`,
368			);
369		return {
370			repository: normalizeURL(receipt.source.repository),
371			revision: receipt.source.revision,
372			archiveSha256: receipt.source.archiveSha256,
373			license: receipt.source.license,
374			licenseSha256: receipt.source.licenseSha256,
375		};
376	}
377	
378	function keys(value: Record<string, unknown>): string[] {
379		return Object.keys(value).sort();
380	}
381	
382	function uniqueCanonical<T>(values: T[]): T[] {
383		const found = new Map(values.map((value) => [canonicalize(value), value]));
384		return [...found.entries()]
385			.sort(([left], [right]) => left.localeCompare(right))
386			.map(([, value]) => value);
387	}
