389	function journeyArtifact(receipt: MigrationReceipt): { path: string; sha256: string } {
390		const artifact = receipt.artifacts.find((item) => path.basename(item.path) === 'journey.json');
391		if (!artifact) throw new Error(`Corpus receipt omits journey artifact: ${receipt.fixture}`);
392		return artifact;
393	}
