395	function reactProjection(value: unknown, fixture: string): JourneyProjection {
396		const item = record(value, `${fixture} journey row`);
397		return {
398			result: string(item.result, `${fixture} journey result`),
399			selectedLocale: string(item.selectedLocale, `${fixture} selected locale`),
400			translatedHeading: string(item.translatedHeading, `${fixture} translated heading`),
401		};
402	}
403	
404	function blockedUrls(value: unknown, fixture: string): string[] {
405		const blocked = record(value, `${fixture} journey row`).blocked;
406		if (!Array.isArray(blocked)) throw new Error(`Corpus ${fixture} blocked observation missing`);
407		return blocked.map((item) => normalizeURL(string(item, `${fixture} blocked URL`))).sort();
408	}
