410	function receiptShape(receipt: MigrationReceipt, journey: unknown[]): Record<string, unknown> {
411		const migration = receipt.migration as unknown as Record<string, unknown>;
412		return {
413			schemaVersion: receipt.schemaVersion,
414			toolingFields: keys(receipt.tooling),
415			migrationFields: keys(migration),
416			journeyFields: uniqueCanonical(
417				journey.map((value) => keys(record(value, `${receipt.fixture} journey row`))),
418			),
419		};
420	}
