422	function assertAggregateFixture(
423		value: unknown,
424		expected: CanonicalReceipt,
425	): Record<string, unknown> {
426		const fixture = record(value, `aggregate fixture ${expected.id}`);
427		if (
428			fixture.id !== expected.id ||
429			fixture.receipt !== expected.path ||
430			(expected.digest !== null && fixture.digest !== expected.digest) ||
431			fixture.result !== 'pass' ||
432			fixture.framework !== expected.framework ||
433			(expected.id === 'angular-phonecat-vite8' &&
434				(fixture.bundler !== 'none-static-to-vite-8' ||
435					fixture.track !== 'angularjs-special-track' ||
436					fixture.runtime !== 'node-16-to-node-24.15.0'))
437		)
438			throw new Error(`Aggregate membership mismatch: ${expected.id}`);
439		return fixture;
440	}
