442	export function deriveCorpusTransactionState(fixtures: unknown): CorpusTransactionState {
443		if (!Array.isArray(fixtures)) throw new Error('Aggregate fixtures must be an array');
444		const byPath = new Map<string, unknown>();
445		const orderedPaths: string[] = [];
446		for (const value of fixtures) {
447			const fixture = record(value, 'aggregate fixture');
448			const receiptPath = string(fixture.receipt, 'aggregate receipt path');
449			if (byPath.has(receiptPath))
450				throw new Error('Aggregate membership contains duplicate receipts');
451			byPath.set(receiptPath, value);
452			orderedPaths.push(receiptPath);
453		}
454		for (const expected of canonicalReceipts) {
455			const value = byPath.get(expected.path);
456			if (!value) throw new Error(`Aggregate is missing receipt: ${expected.path}`);
457			assertAggregateFixture(value, expected);
458			const digest = record(value, `aggregate fixture ${expected.id}`).digest;
459			if (typeof digest !== 'string' || !sha256Pattern.test(digest))
460				throw new Error(`Aggregate digest is invalid: ${expected.id}`);
461		}
462		const angular = byPath.get(ANGULAR_REALWORLD_V15_TO_V16_RECEIPT.path);
463		if (
464			!angular ||
465			canonicalize(record(angular, 'Angular RealWorld aggregate fixture')) !==
466				canonicalize({
467					id: 'angular-realworld-v15-to-v16',
468					framework: 'angular',
469					track: 'angular2-plus-adjacent-major',
470					bundler: 'angular-cli-architect-aot-15-to-16',
471					runtime: 'node-18.20.8',
472					result: 'pass',
473					receipt: ANGULAR_REALWORLD_V15_TO_V16_RECEIPT.path,
474					digest: ANGULAR_REALWORLD_V15_TO_V16_RECEIPT.canonicalDigest,
475				})
476		)
477			throw new Error('Angular RealWorld aggregate membership mismatch');
478		const next = byPath.get(NEXT_KILLED_BY_GOOGLE_RECEIPT_PATH);
479		if (next) {
480			const nextRecord = record(next, 'Killed by Google aggregate fixture');
481			const digest = string(nextRecord.digest, 'Killed by Google aggregate digest');
482			if (
483				!sha256Pattern.test(digest) ||
484				canonicalize(nextRecord) !== canonicalize(nextKilledByGoogleAggregateMember(digest))
485			)
486				throw new Error('Killed by Google aggregate membership mismatch');
487			const witness = byPath.get(WITNESS_ANGULAR_REALWORLD_RECEIPT_PATH);
488			if (witness) {
489				const witnessRecord = record(witness, 'Witness Angular RealWorld aggregate fixture');
490				const witnessDigest = string(
491					witnessRecord.digest,
492					'Witness Angular RealWorld aggregate digest',
493				);
494				if (
495					!sha256Pattern.test(witnessDigest) ||
496					canonicalize(witnessRecord) !==
497						canonicalize(witnessAngularRealworldAggregateMember(witnessDigest))
498				)
499					throw new Error('Witness Angular RealWorld aggregate membership mismatch');
500				const react = byPath.get(WITNESS_REACT_BOILERPLATE_RECEIPT_PATH);
501				if (react) {
502					const reactRecord = record(react, 'Witness React Boilerplate aggregate fixture');
503					const reactDigest = string(
504						reactRecord.digest,
505						'Witness React Boilerplate aggregate digest',
506					);
507					if (
508						!sha256Pattern.test(reactDigest) ||
509						canonicalize(reactRecord) !==
510							canonicalize(witnessReactBoilerplateAggregateMember(reactDigest))
511					)
512						throw new Error('Witness React Boilerplate aggregate membership mismatch');
513					const nextWitness = byPath.get(WITNESS_NEXT_KILLED_BY_GOOGLE_RECEIPT_PATH);
514					if (nextWitness) {
515						const nextWitnessRecord = record(
516							nextWitness,
517							'Witness Next KilledByGoogle aggregate fixture',
518						);
519						const nextWitnessDigest = string(
520							nextWitnessRecord.digest,
521							'Witness Next KilledByGoogle aggregate digest',
522						);
523						if (
524							!sha256Pattern.test(nextWitnessDigest) ||
525							canonicalize(nextWitnessRecord) !==
526								canonicalize(
527									witnessNextKilledByGoogleAggregateMember(nextWitnessDigest),
528								)
529						)
530							throw new Error(
531								'Witness Next KilledByGoogle aggregate membership mismatch',
532							);
533						const avataaars = byPath.get(REACT_AVATAAARS_COMPATIBILITY_RECEIPT_PATH);
534						const calculator = byPath.get(REACT_CALCULATOR_RECEIPT_PATH);
535						const graphiql = byPath.get(REACT_GRAPHIQL_013_RECEIPT_PATH);
536						const candidateOrder = [
537							...orderedPrepublicationReceipts.slice(0, 8),
538							WITNESS_ANGULAR_REALWORLD_RECEIPT_PATH,
