4	import { deriveCorpusTransactionState } from '../src/corpus/conformance.ts';
5	import {
6		parseWitnessReactPapercupsReceipt,
7		REACT_PAPERCUPS_CANONICAL_DIGEST,
8		REACT_PAPERCUPS_RECEIPT_PATH,
9		reactPapercupsAggregateMember,
10		renderWitnessReactPapercupsReceipt,
11		verifyWitnessReactPapercupsEvidence,
12		WITNESS_REACT_PAPERCUPS_RECEIPT_PATH,
13		witnessReactPapercupsAggregateMember,
14		witnessReactPapercupsBehaviorDigest,
15		witnessReactPapercupsDigest,
16		type WitnessReactPapercupsReceipt,
17	} from '../src/receipts/witness-react-papercups.ts';
18	
19	const root = path.resolve(import.meta.dirname, '../../..');
20	
21	async function published(): Promise<WitnessReactPapercupsReceipt> {
22		return parseWitnessReactPapercupsReceipt(
23			JSON.parse(
24				await readFile(path.join(root, WITNESS_REACT_PAPERCUPS_RECEIPT_PATH), 'utf8'),
25			) as unknown,
26		);
27	}
28	
29	function resealed(receipt: WitnessReactPapercupsReceipt): WitnessReactPapercupsReceipt {
30		const copy = structuredClone(receipt);
31		copy.integrity.canonicalDigest = witnessReactPapercupsDigest(copy);
32		return copy;
33	}
34	
35	describe('Papercups direct Witness receipt', () => {
36		it('verifies the published browser proof and its rendered companion', async () => {
37			const verified = await verifyWitnessReactPapercupsEvidence(root);
38			expect(verified.valid).toBe(true);
39			expect(verified.receipt.result).toBe('pass');
40			expect(verified.receipt.runs).toHaveLength(4);
41			expect(verified.receipt.canonicalReceipt.path).toBe(REACT_PAPERCUPS_RECEIPT_PATH);
42			expect(verified.receipt.canonicalReceipt.canonicalDigest).toBe(
43				REACT_PAPERCUPS_CANONICAL_DIGEST,
44			);
45			expect(
46				await readFile(
47					path.join(root, path.dirname(WITNESS_REACT_PAPERCUPS_RECEIPT_PATH), 'receipt.md'),
48					'utf8',
49				),
50			).toBe(renderWitnessReactPapercupsReceipt(verified.receipt));
51		});
52	
53		it('proves one behavior across both lanes and both passes', async () => {
54			const receipt = await published();
55			const digests = new Set(receipt.runs.map((run) => run.behaviorDigest));
56			expect(digests.size).toBe(1);
57			expect([...digests]).toEqual([receipt.mutation.restoredBehaviorDigest]);
58			expect(receipt.runs.map((run) => `${run.lane}:${run.pass}`).sort()).toEqual([
59				'baseline:1',
60				'baseline:2',
61				'migrated:1',
62				'migrated:2',
63			]);
64			for (const run of receipt.runs)
65				expect(witnessReactPapercupsBehaviorDigest(run)).toBe(run.behaviorDigest);
66		});
67	
68		it('records the retained but unregistered create-react-app worker without masking it', async () => {
69			const receipt = await published();
70			const baseline = receipt.runs.filter((run) => run.lane === 'baseline');
71			const migrated = receipt.runs.filter((run) => run.lane === 'migrated');
72			expect(
73				baseline.map((run) =>
74					run.zeroServiceWorkerRuntime.emittedOutputFiles.map((file) => file.path),
75				),
76			).toEqual([['service-worker.js'], ['service-worker.js']]);
77			expect(
78				migrated.map((run) => run.zeroServiceWorkerRuntime.emittedOutputFiles),
79			).toEqual([[], []]);
80			expect(receipt.zeroServiceWorker.emittedOutputFiles.map((file) => file.path)).toEqual([
81				'service-worker.js',
82			]);
83			for (const run of receipt.runs) {
84				expect(run.zeroServiceWorkerRuntime.registration).toBe('application-unregister');
