86				expect(run.zeroServiceWorkerRuntime.workerEvents).toEqual([]);
87				expect(run.zeroServiceWorkerRuntime.checkpoints.map((item) => item.phase)).toEqual([
88					'before-interactions',
89					'after-interactions',
90					'after-online-reload',
91				]);
92				for (const checkpoint of run.zeroServiceWorkerRuntime.checkpoints) {
